draw:
var k = 8.99e9;
var q1 = p.q1 * 1e-6, q2 = p.q2 * 1e-6, r = p.sep;
var F = k * Math.abs(q1 * q2) / (r * r);
var repel = (q1 * q2) > 0;

var yc = H * 0.52;
var frac = 0.18 + 0.55 * (r - 0.05) / 0.45;
var s = W * frac;
var x1 = W / 2 - s / 2, x2 = W / 2 + s / 2;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// axis
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(W * 0.04, yc); ctx.lineTo(W * 0.96, yc); ctx.stroke();

// separation bar
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(x1, yc + 34); ctx.lineTo(x2, yc + 34); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("r = " + r.toFixed(2) + " m", (x1 + x2) / 2, yc + 50);

function blob(x, q, label) {
  var R = 9 + 2.2 * Math.abs(q);
  ctx.fillStyle = q >= 0 ? C.accent : C.figure;
  ctx.beginPath(); ctx.arc(x, yc, R, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = C.paper;
  ctx.fillText(q >= 0 ? "+" : "-", x, yc + 4);
  ctx.fillStyle = C.ink;
  ctx.fillText(label + " = " + q.toFixed(1) + " uC", x, yc - R - 10);
}

function arrow(x, dir, len) {
  ctx.strokeStyle = C.ink;
  ctx.lineWidth = 2;
  var x0 = x + dir * 18, x1b = x + dir * (18 + len);
  ctx.beginPath(); ctx.moveTo(x0, yc); ctx.lineTo(x1b, yc); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x1b, yc);
  ctx.lineTo(x1b - dir * 7, yc - 5);
  ctx.lineTo(x1b - dir * 7, yc + 5);
  ctx.closePath();
  ctx.fillStyle = C.ink; ctx.fill();
}

var Fmax = k * 25e-12 / (0.05 * 0.05);
var len = 12 + 60 * Math.sqrt(Math.min(F / Fmax, 1));
if (F > 0) {
  arrow(x1, repel ? -1 : 1, len);
  arrow(x2, repel ? 1 : -1, len);
}

blob(x1, p.q1, "q1");
blob(x2, p.q2, "q2");

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText(repel ? "like signs: push apart" : "unlike signs: pull together", W * 0.05, H * 0.14);

out.note = "F = " + F.toExponential(3) + " N  on each charge, equal and opposite";
